def unique_digits(x):
    def has_unique_odd_digits(n):
        digits = set()
        while n > 0:
            digit = n % 10
            if digit % 2 == 0 or digit in digits:
                return False
            digits.add(digit)
            n //= 10
        return True

    result = [num for num in x if has_unique_odd_digits(num)]
    return sorted(result)

